import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.DWKxYYJ1.js";var i=JSON.parse(`{"title":"Natural Language Intelligent Web Crawling & RAG Knowledge Building Platform | SyncCrawl","description":"SyncCrawl collects web data and builds RAG knowledge bases using natural language commands. It is an intelligent integrated crawling solution that maximizes operational efficiency by automatically adapting to web structure changes and provides accurate, highly reliable answers without LLM hallucination.","frontmatter":{"title":"Natural Language Intelligent Web Crawling & RAG Knowledge Building Platform | SyncCrawl","description":"SyncCrawl collects web data and builds RAG knowledge bases using natural language commands. It is an intelligent integrated crawling solution that maximizes operational efficiency by automatically adapting to web structure changes and provides accurate, highly reliable answers without LLM hallucination.","head":[["meta",{"name":"keywords","content":"Web Crawling Solution, Intelligent Crawling, Crawling Automation, Integrated Crawling System, Web Data Collection, B2B Knowledge Solution, Research Automation, RAG (Retrieval-Augmented Generation), RAG Knowledge Base Building, LLM Hallucination Prevention, Semantic Search, Context-based Q&A, AI Agent, Vector Storage Integration, Embedding Generation, Korean Optimization, Natural Language Command Crawling, Maximizing Operational Efficiency, Minimizing Additional Development Effort, Auto-adaptive System, Non-developer Crawling, Adaptive Crawling, Automated Selector Re-learning, Dynamic Web Crawling, LangChain4j, Playwright MCP, Vector DB, Cross-platform UI, Multi-browser Support"}],["meta",{"property":"og:title","content":"Natural Language Intelligent Web Crawling & RAG Knowledge Building Platform | SyncCrawl"}],["meta",{"property":"og:description","content":"SyncCrawl collects web data and builds RAG knowledge bases using natural language commands. It is an intelligent integrated crawling solution that maximizes operational efficiency by automatically adapting to web structure changes and provides accurate, highly reliable answers without LLM hallucination."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/synccrawl/"}]],"order":1,"dir":{"order":2}},"headers":[],"relativePath":"en/synccrawl/index.md","filePath":"en/synccrawl/index.md","lastUpdated":1784550136000}`),a={name:`en/synccrawl/index.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<p><strong>SyncCrawl™: Natural Language Intelligent Crawling System</strong></p><p>SyncCrawl™ is an integrated crawling system based on natural language, a next-generation solution for intelligent web content collection and Retrieval-Augmented Generation (RAG)-based knowledge building.</p><p>This platform is designed to <strong>interpret users&#39; complex data collection and analysis commands in natural language</strong>, instantly convert the collected data into an enterprise&#39;s RAG knowledge base, and <strong>build a highly reliable Q&amp;A system</strong>. Going beyond a simple crawling tool, SyncCrawl aims to be an intelligent integrated platform that builds and utilizes an enterprise&#39;s knowledge assets.</p><hr><h2 id="_1-synccrawl-core-technology-stack-and-composition" tabindex="-1">1. SyncCrawl Core Technology Stack and Composition <a class="header-anchor" href="#_1-synccrawl-core-technology-stack-and-composition" aria-label="Permalink to “1. SyncCrawl Core Technology Stack and Composition”">​</a></h2><p>SyncCrawl is built by integrating a leading Java-based AI framework and web automation tools.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Category</th><th style="text-align:left;">Description</th><th style="text-align:left;">Source</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Core Framework</strong></td><td style="text-align:left;">Based on Java&#39;s Spring Boot server architecture.</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>AI Layer</strong></td><td style="text-align:left;">Utilizes natural language processing, RAG engine, and Agent system based on <strong>LangChain4j Agent</strong>.</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>Web Automation</strong></td><td style="text-align:left;">Integrates and uses the <strong>Playwright MCP (Model Context Protocol)</strong> web automation tool.</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>Knowledge Base</strong></td><td style="text-align:left;">Builds a knowledge base through RAG technology and integrates a Vector DB.</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>Frontend</strong></td><td style="text-align:left;">Supports cross-platform UI using <strong>Quasar Framework</strong> and Electron.</td><td style="text-align:left;"></td></tr></tbody></table><hr><h2 id="_2-intelligent-pipeline-architecture" tabindex="-1">2. Intelligent Pipeline Architecture <a class="header-anchor" href="#_2-intelligent-pipeline-architecture" aria-label="Permalink to “2. Intelligent Pipeline Architecture”">​</a></h2><p>SyncCrawl operates an intelligent pipeline that automates the entire process from crawling to data processing and RAG building.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Stage</th><th style="text-align:left;">Detailed Description</th><th style="text-align:left;">Technical Elements</th><th style="text-align:left;">Source</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1. Natural Language Command Interpretation</strong></td><td style="text-align:left;">The <strong>LangChain4j Agent</strong> analyzes the user&#39;s natural language request (e.g., crawling, summarizing) to understand the intent and automate Tool calls.</td><td style="text-align:left;">LangChain4j Agent, Tool</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>2. Intelligent Crawling Execution</strong></td><td style="text-align:left;">The Agent calls the web automation Tool, <strong>Playwright MCP</strong>, according to the identified intent. Playwright supports multiple browsers like Chromium, Firefox, and WebKit, and helps the LLM access and interact with web page elements.</td><td style="text-align:left;">Playwright MCP, Dynamic Web Interaction</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>3. Data Collection</strong></td><td style="text-align:left;">Interacts with the web page to collect HTML content.</td><td style="text-align:left;">Playwright</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>4. Data Processing and Storage</strong></td><td style="text-align:left;">Stores the collected HTML content in a vector database utilizing RAG components.</td><td style="text-align:left;">DocumentSplitter, EmbeddingModel, EmbeddingStore</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>5. RAG-based Q&amp;A</strong></td><td style="text-align:left;">Embeds the user&#39;s question, and the <strong>Retriever</strong> searches for the most similar document Chunks. The retrieved relevant documents are injected as &#39;context&#39; into the prompt of the LLM (e.g., GPT-4) to generate an <strong>accurate and highly reliable answer</strong>.</td><td style="text-align:left;">ConversationalRetrievalAgent, LLM</td><td style="text-align:left;"></td></tr></tbody></table><hr><h2 id="_3-key-feature-areas" tabindex="-1">3. Key Feature Areas <a class="header-anchor" href="#_3-key-feature-areas" aria-label="Permalink to “3. Key Feature Areas”">​</a></h2><p>SyncCrawl provides an integrated knowledge-building environment through three main feature areas.</p><h3 id="i-intelligent-crawling-features" tabindex="-1">I. Intelligent Crawling Features <a class="header-anchor" href="#i-intelligent-crawling-features" aria-label="Permalink to “I. Intelligent Crawling Features”">​</a></h3><ol><li><strong>Natural Language-based Command Processing</strong>: Understands the intent of user requests and automates Tool calls.</li><li><strong>Dynamic Web Interaction</strong>: Provides multi-browser support and network control using Playwright.</li><li><strong>Adaptive Crawling</strong>: Flexibly responds to website UI/UX changes, and commonizes and applies crawling rules for complex sites (over 500). This is made possible through an <strong>automated selector re-learning loop</strong>.</li></ol><h3 id="ii-rag-based-knowledge-building-features" tabindex="-1">II. RAG-based Knowledge Building Features <a class="header-anchor" href="#ii-rag-based-knowledge-building-features" aria-label="Permalink to “II. RAG-based Knowledge Building Features”">​</a></h3><ol><li><strong>Document Splitting and Embedding</strong>: Splits collected content into meaningful Chunks with DocumentSplitter and converts them into high-dimensional vectors using EmbeddingModel. It can <strong>support models for Korean data</strong> to improve embedding quality.</li><li><strong>Vector Storage Integration</strong>: Persistently stores embedded data and is expandable to various Vector DBs such as FAISS, Qdrant, and Weaviate.</li><li><strong>Context-based Q&amp;A</strong>: LLM retrieves saved documents and generates accurate answers based on the context.</li></ol><h3 id="iii-system-management-and-operation-features" tabindex="-1">III. System Management and Operation Features <a class="header-anchor" href="#iii-system-management-and-operation-features" aria-label="Permalink to “III. System Management and Operation Features”">​</a></h3><ol><li><strong>Crawling Setting Management UI</strong>: Provides a UI to visually set crawling target URLs, rules (CSS Selector), data extraction patterns, scheduling, etc.</li><li><strong>Cross-platform UI</strong>: Supports desktop, web, and mobile app development with a single codebase utilizing the Quasar Framework and Electron.</li><li><strong>Real-time Monitoring</strong>: Provides a dashboard showing the status of ongoing crawling tasks on the server, success/failure status, data collection amount, etc., through Spring REST API integration.</li><li><strong>Interactive Settings and Memory</strong>: Analyzes the intent of conversations when setting crawling rules through NLP intent analysis, and manages conversation history and interaction history per user (can utilize Redis-based LangChain4j Memory).</li></ol><hr><h2 id="_4-synccrawl-s-core-competitiveness-and-differentiated-value" tabindex="-1">4. SyncCrawl&#39;s Core Competitiveness and Differentiated Value <a class="header-anchor" href="#_4-synccrawl-s-core-competitiveness-and-differentiated-value" aria-label="Permalink to “4. SyncCrawl&#39;s Core Competitiveness and Differentiated Value”">​</a></h2><p>SyncCrawl overcomes the limitations of existing crawling systems and provides differentiated value that maximizes knowledge utilization in an enterprise environment.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Competitiveness Factor</th><th style="text-align:left;">Value of SyncCrawl</th><th style="text-align:left;">Source</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Natural Language Interface</strong></td><td style="text-align:left;">Allows crawling commands in natural language without complex coding, making it <strong>easy for non-developers to use</strong>.</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>Auto-adaptive System</strong></td><td style="text-align:left;">Automatically responds to website UI/UX changes, <strong>drastically reducing maintenance costs</strong> and maximizing operational efficiency. It can handle over 500 different websites.</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>Accuracy and Reliability</strong></td><td style="text-align:left;">Prevents LLM hallucination and provides reliable answers <strong>based on actually collected documents</strong>.</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>Ready-to-use Knowledge</strong></td><td style="text-align:left;">Collected data is instantly <strong>converted into a RAG knowledge base</strong> and immediately used for Q&amp;A.</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>Korean Optimization</strong></td><td style="text-align:left;">Realizes high-quality embedding and search for Korean content.</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>Enterprise-grade Stability</strong></td><td style="text-align:left;">Ensures stable operation with a robust architecture based on Spring Boot and real-time monitoring.</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>Scalability</strong></td><td style="text-align:left;">Can be flexibly expanded in line with enterprise growth through support for various Vector DBs and a cross-platform UI.</td><td style="text-align:left;"></td></tr></tbody></table>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};